extract_js:
(S) => {
  const q = (s, r = document) => { try { return s ? r.querySelector(s) : null; } catch (e) { return null; } };
  const qa = (s, r = document) => { try { return s ? [...r.querySelectorAll(s)] : []; } catch (e) { return []; } };
  const t = (el) => (el ? el.textContent.trim() : "");
  const main = q('div[role="main"]') || document;
  const name = t(q(S.title)) || t(q('h1', main));

  let phone = "";
  const pb = q(S.phone);
  if (pb) phone = t(q(S.item_value, pb)) || (pb.getAttribute('data-item-id') || '').replace('phone:tel:', '') ||
    (pb.getAttribute('aria-label') || '').replace(/^[^:]*:\s*/, '');

  const wa = q(S.website);
  const website = wa ? wa.href : "";

  const ab = q(S.address);
  const address = ab ? (t(q(S.item_value, ab)) || (ab.getAttribute('aria-label') || '').replace(/^[^:]*:\s*/, '')) : "";

  const category = t(q(S.category));

  let rating = "", reviews = "";
  const f7 = q(S.rating_box);
  if (f7) {
    rating = t(q('span[aria-hidden="true"]', f7));
    const rv = qa('span[aria-label]', f7).find(s => /yorum|review|değerlendirme/i.test(s.getAttribute('aria-label')));
    if (rv) reviews = rv.getAttribute('aria-label') || t(rv);
  }
  if (!rating) {
    const st = qa('[aria-label]', main).find(e => /yıldızlı|stars/i.test(e.getAttribute('aria-label')));
    if (st) rating = (st.getAttribute('aria-label').match(/[\d.,]+/) || [""])[0];
  }
  if (!reviews) {
    const el = qa('[aria-label]', main).find(e => /^[\d.,]+\s+(yorum|review)/i.test(e.getAttribute('aria-label')));
    if (el) reviews = el.getAttribute('aria-label');
  }

  const DAY = /^(Pazartesi|Salı|Çarşamba|Perşembe|Cuma|Cumartesi|Pazar|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\b/i;
  const hours = qa('table tr', main).map(r => r.innerText.replace(/\s+/g, ' ').trim()).filter(x => DAY.test(x)).join('; ');

  let price = "";
  const pe = qa('[aria-label]', main).find(e => /^(Fiyat|Price)/i.test(e.getAttribute('aria-label')));
  if (pe) price = pe.getAttribute('aria-label').replace(/^[^:]*:\s*/, '');

  const txt = main.innerText || "";
  const status = /Kalıcı olarak kapalı|Permanently closed/i.test(txt) ? "Kalıcı olarak kapalı"
    : (/Geçici olarak kapalı|Temporarily closed/i.test(txt) ? "Geçici olarak kapalı" : "");

  const unclaimed = qa('a, button', main).some(e =>
    /sahibi (siz )?misiniz|işletmeyi sahiplen|claim this business|own this business/i.test((e.getAttribute('aria-label') || '') + ' ' + e.textContent));

  return { name, phone, website, address, category, rating, reviews, hours, price, status, unclaimed };
}
